<?php
namespace App\Http\Controllers; use App\Domain\Commerce\Models\Order; use Illuminate\Http\Request; use Inertia\Inertia; class AdminOrdersController {public function index(Request $r){$q=Order::latest('placed_at');if($r->filled('q'))$q->where(fn($x)=>$x->where('order_number','ilike','%'.$r->q.'%')->orWhere('customer_email','ilike','%'.$r->q.'%'));foreach(['payment_status','fulfillment_status','order_status'] as $f)if($r->filled($f))$q->where($f,$r->$f);return Inertia::render('Admin/Orders/Index',['orders'=>$q->paginate(25)->withQueryString()]);} public function show(Order $order){$order->load(['items.product.images','addresses','payments.events','shipments.items','returns.items','refunds','statusHistory']);return Inertia::render('Admin/Orders/Show',['order'=>$order]);}}
